function logo(){return `<a class="logo" href="/LANG/" aria-label="PTS Appliance Repair home"><svg viewBox="0 0 52 52" aria-hidden="true"><path d="M26 3 45 10v14c0 12-8 21-19 25C15 45 7 36 7 24V10Z" fill="#A10045"/><path d="m18 32 14-14m-11-2a6 6 0 0 0 7 7l-9 9a3 3 0 1 0 4 4l9-9a6 6 0 0 0 7-7l-5 3-5-5 3-5a6 6 0 0 0-11 3Z" fill="none" stroke="#fff" stroke-width="3" stroke-linecap="round"/></svg><span><b>PTS</b><small>Appliance Repair</small></span></a>`}
function esc(s){return s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function url(lang,city,service){return `${DOMAIN}/${lang}/${city}/${service}.html`}
function alternate(lang,city,service){return `<link rel="canonical" href="${url(lang,city,service)}"><link rel="alternate" hreflang="en" href="${url('en',city,service)}"><link rel="alternate" hreflang="fr" href="${url('fr',city,service)}"><link rel="alternate" hreflang="x-default" href="${url('en',city,service)}">`}
function faqData(lang, s, city){return lang==='en' ? [
  [`Can you provide same-day ${s.en.toLowerCase()} in ${city}?`,`Yes. Call early to check today's technician availability in ${city}.`],
  [`How much is the diagnostic visit?`,`The diagnostic fee is ${DIAGNOSTIC_FEE}. You receive the diagnosis and repair options before approving any work.`],
  [`Which brands and appliance types do you repair?`,`Our experienced technicians service all major brands, including electric and gas appliances.`]
] : [
  [`Offrez-vous la ${s.fr.toLowerCase()} le jour même à ${city}?`,`Oui. Appelez tôt pour vérifier la disponibilité d’un technicien aujourd’hui à ${city}.`],
  [`Combien coûte la visite diagnostique?`,`Les frais de diagnostic sont de ${DIAGNOSTIC_FEE}. Vous recevez le diagnostic et les options avant d’approuver les travaux.`],
  [`Quelles marques et quels appareils réparez-vous?`,`Nos techniciens expérimentés réparent toutes les grandes marques, y compris les appareils électriques et au gaz.`]
]}
function schema(lang,s,city,pageUrl,faqs){const imageUrl=`${DOMAIN}/assets/images/appliances/${s.image}.webp`;return JSON.stringify([
  {'@context':'https://schema.org','@type':'LocalBusiness','@id':`${pageUrl}#business`,name:'PTS Appliance Repair',url:`${DOMAIN}/${lang}/`,telephone:'+1-343-571-9684',email:EMAIL,image:imageUrl,priceRange:'$$',paymentAccepted:'Interac, Cash',openingHours:'Mo-Sa 08:00-20:00',areaServed:{'@type':'City',name:city},knowsLanguage:['en','fr']},
  {'@context':'https://schema.org','@type':'Service','@id':`${pageUrl}#service`,name:`${s[lang]} — ${city}`,serviceType:s[lang],url:pageUrl,image:imageUrl,provider:{'@id':`${pageUrl}#business`},areaServed:{'@type':'City',name:city}},
  {'@context':'https://schema.org','@type':'FAQPage',mainEntity:faqs.map(([q,a])=>({'@type':'Question',name:q,acceptedAnswer:{'@type':'Answer',text:a}}))},
  {'@context':'https://schema.org','@type':'BreadcrumbList',itemListElement:[{'@type':'ListItem',position:1,name:lang==='en'?'Home':'Accueil',item:`${DOMAIN}/${lang}/`},{'@type':'ListItem',position:2,name:s[lang],item:`${DOMAIN}/${lang}/services/${s.slug}.html`},{'@type':'ListItem',position:3,name:city,item:pageUrl}]}
])}
function header(lang,otherHref){const t=lang==='en'; return `<div class="alert"><span>${t?HOURS_EN:HOURS_FR}</span><a href="mailto:${EMAIL}">${EMAIL}</a><a href="tel:${PHONE_URI}">${t?'Emergency line':'Ligne d’urgence'} · ${PHONE}</a></div><header>${logo().replace('LANG',lang)}<nav aria-label="${t?'Main navigation':'Navigation principale'}"><a href="/${lang}/#services">${t?'Services':'Services'}</a><a href="/${lang}/#about">${t?'About':'À propos'}</a><a href="/${lang}/#reviews">${t?'Our promise':'Nos engagements'}</a><a href="/${lang}/contact.html">Contact</a></nav><div class="actions"><a class="lang" href="${otherHref}" hreflang="${t?'fr':'en'}">${t?'FR':'EN'}</a><a class="btn compact" href="/${lang}/contact.html">${t?'Book now':'Réserver'} · ${PHONE}</a></div></header>`}
function booking(lang,selectedService='',selectedCity=''){const t=lang==='en';return `<form class="booking" id="booking"><label>${t?'Appliance':'Appareil'}<select name="service" required><option value="">${t?'Select appliance':'Choisir un appareil'}</option>${services.map(s=>`<option value="${s.slug}" ${s.slug===selectedService?'selected':''}>${s[lang]}</option>`).join('')}</select></label><label>${t?'City':'Ville'}<select name="city" required><option value="">${t?'Select city':'Choisir une ville'}</option>${cities.map(([name,slug])=>`<option value="${slug}" ${slug===selectedCity?'selected':''}>${name}</option>`).join('')}</select></label><label>${t?'Phone':'Téléphone'}<input name="phone" inputmode="tel" autocomplete="tel" placeholder="343-555-0123" required></label><button class="btn whatsapp-submit" type="submit">${t?'Request on WhatsApp':'Demander sur WhatsApp'}</button><a class="form-contact-link" href="/${lang}/contact.html">${t?'Prefer the contact form?':'Vous préférez le formulaire de contact?'} →</a><p class="form-note" aria-live="polite"></p></form>`}
function commonSections(lang,s,city){const t=lang==='en'; const symptoms=(t?s.sym:s.symFr); return `<section class="trust wrap"><article><b>✓</b><strong>${t?'Experienced technicians':'Techniciens expérimentés'}</strong></article><article><b>⚡</b><strong>${t?'Same-day service':'Service le jour même'}</strong></article><article><b>90</b><strong>${t?'90-day parts & labour warranty':'Garantie pièces et main-d’œuvre de 90 jours'}</strong></article></section>
<section class="section wrap process" id="about"><span class="eyebrow">${t?'Simple, honest service':'Un service simple et transparent'}</span><h2>${t?'From appliance trouble to a clear repair plan':'De la panne à un plan de réparation clair'}</h2><div class="steps"><article><b>01</b><h3>${t?'Tell us the issue':'Décrivez le problème'}</h3><p>${t?'Choose your appliance and city, then share the best number to reach you.':'Choisissez l’appareil et la ville, puis indiquez le meilleur numéro pour vous joindre.'}</p></article><article><b>02</b><h3>${t?'Confirm the visit':'Confirmez la visite'}</h3><p>${t?'Our team contacts you to confirm technician availability and a convenient window.':'Notre équipe vous contacte pour confirmer la disponibilité et une plage pratique.'}</p></article><article><b>03</b><h3>${t?'Approve the repair':'Approuvez la réparation'}</h3><p>${t?'You receive the diagnosis and repair options before any approved work begins.':'Vous recevez le diagnostic et les options avant le début de tout travail approuvé.'}</p></article></div><div class="approval-note"><strong>${t?'No surprise work.':'Aucun travail surprise.'}</strong> ${t?'The repair starts only after you understand and approve the recommended option.':'La réparation commence seulement lorsque vous comprenez et approuvez l’option recommandée.'}</div></section>
<section class="section diagnostic"><div class="wrap split"><div><span class="eyebrow">${t?'Quick diagnostic':'Diagnostic rapide'}</span><h2>${t?'What is your appliance doing?':'Quel problème présente votre appareil?'}</h2><p>${t?'Choose a symptom and speak directly with our dispatch team.':'Choisissez un symptôme et parlez directement à notre équipe.'}</p></div><div class="symptoms">${symptoms.map((x,i)=>`<button data-symptom="${esc(x)}"><span>${i+1}</span>${esc(x)}</button>`).join('')}<a class="btn diagnostic-call" href="tel:${PHONE_URI}" hidden>${t?'Call now about this issue':'Appelez maintenant pour ce problème'}</a></div></div></section>
<section class="section wrap" id="brands"><span class="eyebrow">${t?'All brands serviced':'Toutes les marques réparées'}</span><h2>${t?'One call for every major appliance brand':'Un seul appel pour toutes les grandes marques'}</h2><p class="section-intro">${t?'Our experienced technicians service electric and gas appliances across all major brands.':'Nos techniciens expérimentés réparent les appareils électriques et au gaz de toutes les grandes marques.'}</p><div class="brands brand-tags">${brands.map(x=>`<div>${x}</div>`).join('')}</div><div class="center-cta"><a class="btn" href="tel:${PHONE_URI}">${t?'Book an appointment':'Prendre rendez-vous'}</a></div></section>
<section class="section reviews" id="reviews"><div class="wrap"><span class="eyebrow">${t?'Our service commitment':'Nos engagements de service'}</span><h2>${t?'What you can expect from PTS':'Ce que vous pouvez attendre de PTS'}</h2><div class="cards commitments"><article><b>01</b><h3>${t?'Clear approval':'Approbation claire'}</h3><p>${t?'We explain the diagnosis and repair options before beginning approved work.':'Nous expliquons le diagnostic et les options avant de commencer les travaux approuvés.'}</p></article><article><b>02</b><h3>${t?'Respectful service':'Service respectueux'}</h3><p>${t?'We work carefully in your home and keep the service area orderly.':'Nous travaillons avec soin dans votre domicile et gardons la zone de travail ordonnée.'}</p></article><article><b>03</b><h3>${t?'Direct communication':'Communication directe'}</h3><p>${t?'Call, text or use WhatsApp to discuss your appliance and appointment availability.':'Appelez, textez ou utilisez WhatsApp pour discuter de votre appareil et des disponibilités.'}</p></article></div><p class="honesty-note">${t?'PTS is building its local review history. Verified customer feedback will be published here as it becomes available.':'PTS développe actuellement son historique d’avis locaux. Les commentaires clients vérifiés seront publiés ici lorsqu’ils seront disponibles.'}</p></div></section>
<section class="photo"><div class="wrap split"><div><span class="eyebrow">${t?'Faster identification':'Identification plus rapide'}</span><h2>${t?'Send a photo of the appliance model tag':'Envoyez une photo de la plaque signalétique'}</h2><p>${t?'A clear model-number photo helps our team prepare before your visit.':'Une photo claire du numéro de modèle aide notre équipe à se préparer.'}</p></div><div class="photo-actions"><a class="btn" href="sms:${PHONE_URI}?body=${encodeURIComponent(t?'Hi PTS, I would like to send a photo of my appliance model tag.':'Bonjour PTS, je souhaite envoyer une photo de la plaque signalétique de mon appareil.')}">SMS</a><a class="btn outline" href="https://wa.me/13435719684?text=${encodeURIComponent(t?'Hi PTS, I would like to send a photo of my appliance model tag.':'Bonjour PTS, je souhaite envoyer une photo de la plaque signalétique de mon appareil.')}" rel="noopener">WhatsApp</a></div></div></section>`}
function footer(lang){const t=lang==='en';return `<footer><div class="wrap footer-grid">${logo().replace('LANG',lang)}<p>${t?'Professional appliance repair across the Greater Toronto Area.':'Réparation professionnelle d’électroménagers dans la région du Grand Toronto.'}</p><a href="tel:${PHONE_URI}">${PHONE}</a></div><small>© ${new Date().getFullYear()} PTS Appliance Repair</small></footer><div class="mobile-bar"><span>${t?'Same-Day Available':'Service le jour même'}</span><a href="tel:${PHONE_URI}">${t?'Call':'Appelez'} ${PHONE}</a></div>`}
function shell({lang,title,description,canonical,alternates,body,jsonLd=''}){const elfsight=body.includes('elfsight-app-')?'<script src="https://elfsightcdn.com/platform.js" async></script>':'';const imageMatch=body.match(/src="(\/assets\/images\/appliances\/[^"]+)"/);const socialImage=imageMatch?`${DOMAIN}${imageMatch[1]}`:'';return `<!doctype html><html lang="${lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)}</title><meta name="description" content="${esc(description)}"><meta name="theme-color" content="#A10045"><meta property="og:title" content="${esc(title)}"><meta property="og:description" content="${esc(description)}"><meta property="og:type" content="website">${canonical?`<meta property="og:url" content="${canonical}"><link rel="canonical" href="${canonical}">`:''}${socialImage?`<meta property="og:image" content="${socialImage}">`:''}${alternates||''}<link rel="stylesheet" href="/assets/styles.css">${jsonLd?`<script type="application/ld+json">${jsonLd}</script>`:''}${elfsight}</head><body>${body}<script src="/assets/app.js" defer></script></body></html>`}
function links(lang,s,citySlug){const t=lang==='en';return `<section class="section wrap internal" id="services"><h2>${t?'More appliance services in this city':'Autres services dans cette ville'}</h2><div class="link-grid">${services.filter(x=>x.slug!==s.slug).map(x=>`<a href="/${lang}/${citySlug}/${x.slug}.html">${x[lang]}</a>`).join('')}</div><h2>${t?`${s.en} in other GTA cities`:`${s.fr} dans d’autres villes du Grand Toronto`}</h2><div class="link-grid">${cities.filter(x=>x[1]!==citySlug).map(([name,slug])=>`<a href="/${lang}/${slug}/${s.slug}.html">${name}</a>`).join('')}</div></section>`}
function landing(lang,s,city,citySlug){const t=lang==='en', other=lang==='en'?'fr':'en';const title=t?`Same-Day ${s.en} in ${city} | Call ${PHONE}`:`${s.fr} le jour même à ${city} | ${PHONE}`;const desc=t?`Professional ${s.en.toLowerCase()} in ${city}. Same-day appointments, major brands and a 90-day parts and labour warranty. Call ${PHONE}.`:`Service professionnel de ${s.fr.toLowerCase()} à ${city}. Rendez-vous le jour même et garantie de 90 jours. Appelez le ${PHONE}.`;const pageUrl=url(lang,citySlug,s.slug);const faqs=faqData(lang,s,city); const body=`${header(lang,`/${other}/${citySlug}/${s.slug}.html`)}<main><section class="hero"><div class="wrap hero-grid"><div><span class="eyebrow">${t?'Trusted GTA appliance technicians':'Techniciens de confiance dans le Grand Toronto'}</span><h1>${title}</h1><p>${t?`Prompt, professional ${s.en.toLowerCase()} for homes in ${city}. Get a clear diagnosis and practical repair options.`:`Service rapide et professionnel de ${s.fr.toLowerCase()} pour les résidences de ${city}. Diagnostic clair et options pratiques.`}</p><div class="hero-actions"><a class="btn" href="tel:${PHONE_URI}">${t?'Call for same-day service':'Appelez pour un service le jour même'}</a><a class="text-link" href="#booking">${t?'Book online →':'Réserver en ligne →'}</a></div></div>${booking(lang,s.slug,citySlug)}</div></section>${commonSections(lang,s,city)}<section class="section wrap faq"><span class="eyebrow">FAQ</span><h2>${t?`${s.en} questions in ${city}`:`Questions sur la ${s.fr.toLowerCase()} à ${city}`}</h2>${faqs.map(([q,a])=>`<details><summary>${esc(q)}</summary><p>${esc(a)}</p></details>`).join('')}</section>${links(lang,s,citySlug)}</main>${footer(lang)}`;return shell({lang,title,description:desc,alternates:alternate(lang,citySlug,s.slug).replace(`<link rel="canonical" href="${pageUrl}">`,''),canonical:pageUrl,body,jsonLd:schema(lang,s,city,pageUrl,faqs)})}
function homepage(lang){const t=lang==='en',other=t?'fr':'en';const title=t?'PTS Appliance Repair | Same-Day GTA Service':'PTS Appliance Repair | Service le jour même dans le Grand Toronto';const desc=t?`Professional appliance repair across 12 GTA cities. Same-day appointments. Call ${PHONE}.`:`Réparation professionnelle d’électroménagers dans 12 villes du Grand Toronto. Appelez le ${PHONE}.`;const cards=services.map(s=>`<a class="service-card" href="/${lang}/toronto/${s.slug}.html"><span>↗</span><h3>${s[lang]}</h3><p>${t?'Diagnosis and repair for most major brands.':'Diagnostic et réparation des grandes marques.'}</p></a>`).join('');const heroS=services[0];const body=`${header(lang,`/${other}/`)}<main><section class="hero home"><div class="wrap hero-grid"><div><span class="eyebrow">${t?'Same-day appliance repair across the GTA':'Réparation le jour même dans le Grand Toronto'}</span><h1>${t?'Appliance trouble? Get it fixed without the runaround.':'Un appareil en panne? Réglez le problème sans complications.'}</h1><p>${t?'Local technicians, straightforward diagnosis and professional repairs for all major home appliances.':'Techniciens locaux, diagnostic clair et réparations professionnelles de tous les gros électroménagers.'}</p><div class="hero-actions"><a class="btn" href="tel:${PHONE_URI}">${t?'Call':'Appelez'} ${PHONE}</a><a class="text-link" href="#services">${t?'Explore services →':'Voir les services →'}</a></div></div>${booking(lang)}</div></section><section class="trust wrap"><article><b>✓</b><strong>${t?'Licensed technicians':'Techniciens qualifiés'}</strong></article><article><b>⚡</b><strong>${t?'Same-day service':'Service le jour même'}</strong></article><article><b>90</b><strong>${t?'90-day warranty':'Garantie de 90 jours'}</strong></article></section><section class="section wrap" id="services"><span class="eyebrow">${t?'What we repair':'Nos réparations'}</span><h2>${t?'Seven appliance specialties, one trusted team':'Sept spécialités, une équipe de confiance'}</h2><div class="service-grid">${cards}</div></section>${commonSections(lang,heroS,t?'your area':'votre secteur')}<section class="section wrap internal"><h2>${t?'Service areas':'Zones desservies'}</h2><div class="link-grid">${cities.map(([name,slug])=>`<a href="/${lang}/${slug}/refrigerator-repair.html">${name}</a>`).join('')}</div></section></main>${footer(lang)}`;return shell({lang,title,description:desc,canonical:`${DOMAIN}/${lang}/`,alternates:`<link rel="alternate" hreflang="en" href="${DOMAIN}/en/"><link rel="alternate" hreflang="fr" href="${DOMAIN}/fr/"><link rel="alternate" hreflang="x-default" href="${DOMAIN}/en/">`,body})}

const css = `:root{--accent:#A10045;--dark:#0F172A;--bg:#F8FAFC;--white:#fff;--muted:#64748B;--line:#E2E8F0;--radius:18px;--shadow:0 18px 50px rgba(15,23,42,.1)}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;color:var(--dark);background:var(--bg);font-family:Inter,ui-sans-serif,system-ui,-apple-system,Segoe UI,sans-serif;line-height:1.6}a{color:inherit;text-decoration:none}.wrap{width:min(1160px,calc(100% - 40px));margin-inline:auto}.alert{padding:7px 20px;text-align:center;background:var(--dark);color:#fff;font-size:.85rem}.alert a{font-weight:800;color:#f9a8d4}header{height:82px;padding:0 max(20px,calc((100% - 1160px)/2));display:flex;align-items:center;justify-content:space-between;background:#fff;border-bottom:1px solid var(--line);position:sticky;top:0;z-index:20}.logo{display:flex;align-items:center;gap:10px;line-height:1}.logo svg{width:44px;height:44px}.logo span{display:grid}.logo b{font-size:1.4rem}.logo small{font-size:.72rem;color:var(--muted);margin-top:5px}nav{display:flex;gap:28px;font-weight:650}nav a:hover,.text-link:hover{color:var(--accent)}.actions{display:flex;align-items:center;gap:13px}.lang{font-weight:850;border:1px solid var(--line);padding:7px 10px;border-radius:9px}.btn{display:inline-flex;align-items:center;justify-content:center;border:0;border-radius:12px;background:var(--accent);color:#fff;font:inherit;font-weight:800;padding:14px 20px;cursor:pointer;box-shadow:0 8px 20px rgba(161,0,69,.2)}.btn:hover{filter:brightness(.92);transform:translateY(-1px)}.btn.compact{padding:11px 15px}.hero{padding:80px 0 70px;background:radial-gradient(circle at 12% 20%,rgba(161,0,69,.12),transparent 30%),linear-gradient(135deg,#fff,#f8fafc)}.hero-grid,.split{display:grid;grid-template-columns:1.1fr .9fr;align-items:center;gap:70px}.eyebrow{display:inline-block;color:var(--accent);font-size:.78rem;font-weight:900;letter-spacing:.13em;text-transform:uppercase}.hero h1{font-size:clamp(2.55rem,5vw,4.5rem);line-height:1.03;letter-spacing:-.055em;margin:15px 0 22px;max-width:800px}.hero p{font-size:1.16rem;color:#475569;max-width:650px}.hero-actions{display:flex;align-items:center;gap:24px;margin-top:30px}.text-link{font-weight:850}.booking{background:#fff;border:1px solid var(--line);border-top:5px solid var(--accent);border-radius:var(--radius);padding:26px;box-shadow:var(--shadow);display:grid;gap:13px}.booking label{font-size:.8rem;font-weight:800;color:#475569}.booking input,.booking select{width:100%;margin-top:5px;padding:13px;border:1px solid #CBD5E1;border-radius:10px;background:#fff;color:var(--dark);font:inherit}.booking input:focus,.booking select:focus{outline:3px solid rgba(161,0,69,.15);border-color:var(--accent)}.form-note{margin:0;font-size:.8rem;color:var(--accent);font-weight:700}.trust{display:grid;grid-template-columns:repeat(3,1fr);background:#fff;border-radius:16px;box-shadow:var(--shadow);margin-top:-30px;position:relative;z-index:2}.trust article{display:flex;align-items:center;justify-content:center;gap:12px;padding:25px;border-right:1px solid var(--line)}.trust article:last-child{border:0}.trust b{display:grid;place-items:center;width:36px;height:36px;border-radius:50%;background:#fce7f3;color:var(--accent)}.section{padding:90px 0}.section h2,.photo h2{font-size:clamp(2rem,4vw,3.1rem);line-height:1.1;letter-spacing:-.04em;margin:12px 0 35px}.service-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.service-card,.cards article{background:#fff;padding:26px;border:1px solid var(--line);border-radius:15px;transition:.2s}.service-card:hover{border-color:var(--accent);transform:translateY(-4px);box-shadow:var(--shadow)}.service-card span{float:right;color:var(--accent);font-size:1.4rem}.service-card h3{font-size:1.2rem}.service-card p{color:var(--muted)}.diagnostic{background:var(--dark);color:#fff}.diagnostic p{color:#CBD5E1}.symptoms{display:grid;gap:12px}.symptoms button{display:flex;align-items:center;gap:13px;padding:16px;background:#1E293B;color:#fff;border:1px solid #334155;border-radius:12px;font:inherit;font-weight:750;text-align:left;cursor:pointer}.symptoms button:hover,.symptoms button.active{border-color:#f472b6;background:#3b1630}.symptoms button span{display:grid;place-items:center;width:29px;height:29px;border-radius:50%;background:var(--accent)}.brands{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.brands div{padding:26px;text-align:center;border:1px solid var(--line);background:#fff;border-radius:12px;font-weight:850}.reviews{background:#fff}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}.cards article{background:var(--bg)}.stars{color:#EAB308;letter-spacing:.15em}.photo{padding:70px 0;background:#fce7f3}.photo-actions{display:flex;gap:14px;justify-content:flex-end}.outline{color:var(--accent);background:#fff;border:1px solid var(--accent);box-shadow:none}.faq{max-width:900px}.faq details{background:#fff;border:1px solid var(--line);border-radius:12px;padding:18px 20px;margin:12px 0}.faq summary{font-weight:850;cursor:pointer}.faq p{color:#475569}.internal{padding-top:55px}.internal h2{font-size:1.8rem;margin-top:35px}.link-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.link-grid a{padding:13px 15px;background:#fff;border:1px solid var(--line);border-radius:9px;font-weight:700}.link-grid a:hover{color:var(--accent);border-color:var(--accent)}footer{background:var(--dark);color:#fff;padding:55px 0 20px}.footer-grid{display:grid;grid-template-columns:1fr 1.5fr .5fr;align-items:center;gap:30px}.footer-grid .logo small,.footer-grid p{color:#94A3B8}footer>small{display:block;text-align:center;margin-top:45px;color:#64748B}.mobile-bar{display:none}@media(max-width:900px){nav{display:none}.hero-grid,.split{grid-template-columns:1fr;gap:38px}.hero{padding-top:55px}.trust{grid-template-columns:1fr;margin-top:20px}.trust article{border-right:0;border-bottom:1px solid var(--line)}.service-grid,.cards{grid-template-columns:repeat(2,1fr)}.brands,.link-grid{grid-template-columns:repeat(2,1fr)}.photo-actions{justify-content:flex-start}.footer-grid{grid-template-columns:1fr}}@media(max-width:600px){body{padding-bottom:70px}.wrap{width:min(100% - 28px,1160px)}header{height:70px;padding:0 14px}.logo svg{width:38px}.logo small{display:none}.actions .btn{display:none}.hero h1{font-size:2.65rem}.hero-actions{align-items:flex-start;flex-direction:column}.service-grid,.cards{grid-template-columns:1fr}.brands{grid-template-columns:repeat(2,1fr)}.section{padding:65px 0}.mobile-bar{position:fixed;display:flex;align-items:center;justify-content:space-between;z-index:50;bottom:0;left:0;right:0;background:#fff;border-top:1px solid var(--line);padding:9px 12px}.mobile-bar span{font-size:.72rem;font-weight:800}.mobile-bar a{background:var(--accent);color:#fff;border-radius:9px;padding:10px 13px;font-weight:850}.photo-actions{flex-direction:column}.link-grid{grid-template-columns:1fr 1fr}}`;
const js = `document.addEventListener('DOMContentLoaded',()=>{document.querySelectorAll('#booking').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const d=new FormData(form),phone=String(d.get('phone')||'').trim(),service=form.elements.service.selectedOptions[0].text,city=form.elements.city.selectedOptions[0].text,isFr=document.documentElement.lang==='fr';const message=isFr?'Bonjour PTS Appliance Repair,\\n\\nJe souhaite demander un service.\\n\\nAppareil : '+service+'\\nVille : '+city+'\\nMon téléphone : '+phone+'\\n\\nPouvez-vous confirmer votre disponibilité?':'Hello PTS Appliance Repair,\\n\\nI would like to request service.\\n\\nAppliance: '+service+'\\nCity: '+city+'\\nMy phone: '+phone+'\\n\\nCan you confirm your availability?';form.querySelector('.form-note').textContent=isFr?'Ouverture de WhatsApp…':'Opening WhatsApp…';location.href='https://wa.me/13435719684?text='+encodeURIComponent(message)}));document.querySelectorAll('[data-symptom]').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('[data-symptom]').forEach(b=>b.classList.remove('active'));btn.classList.add('active');const a=btn.parentElement.querySelector('.diagnostic-call');a.hidden=false;a.textContent=(document.documentElement.lang==='fr'?'Appelez pour : ':'Call about: ')+btn.dataset.symptom}));});`;

function contactPage(lang){const t=lang==='en';const other=t?'fr':'en';const appId=t?'elfsight-app-26dfa6db-c6b2-4888-b554-03c4ba4f56cf':'elfsight-app-7631b7d1-8e7f-4b3e-ae91-f4196629ad6d';const canonical=`${DOMAIN}/${lang}/contact.html`;const body=`${header(lang,`/${other}/contact.html`)}<main class="contact-page"><section class="section wrap"><div class="contact-page-grid"><div class="contact-info-panel"><span class="eyebrow">${t?'Contact PTS':'Contactez PTS'}</span><h1>${t?'Contact us':'Nous joindre'}</h1><p class="contact-lead">${t?'Call us or send the form. Our team will contact you to confirm technician availability.':'Appelez-nous ou envoyez le formulaire. Notre équipe vous contactera pour confirmer la disponibilité d’un technicien.'}</p><div class="contact-row"><b>☎</b><div><small>${t?'Phone':'Téléphone'}</small><a href="tel:${PHONE_URI}">${PHONE}</a></div></div><div class="contact-row"><b>✉</b><div><small>${t?'Email':'Courriel'}</small><a href="mailto:${EMAIL}">${EMAIL}</a></div></div><div class="contact-row"><b>⌖</b><div><small>${t?'Service areas':'Zones desservies'}</small><p>${cities.map(c=>c[0]).join(', ')}</p></div></div><div class="contact-row"><b>◷</b><div><small>${t?'Business hours':'Heures d’ouverture'}</small><p>${t?HOURS_EN:HOURS_FR}<br>${t?'Sunday: Closed':'Dimanche : fermé'}<br>${t?'Emergency line available':'Ligne d’urgence disponible'}</p></div></div><div class="contact-facts"><span>${t?`Diagnostic: ${DIAGNOSTIC_FEE}`:`Diagnostic : ${DIAGNOSTIC_FEE}`}</span><span>${t?'Interac & cash':'Interac et comptant'}</span></div></div><div class="contact-form-panel"><h2>${t?'Send us a message':'Envoyez-nous un message'}</h2><div class="${appId}" data-elfsight-app-lazy></div><noscript>${t?'JavaScript is required to load this form. Call':'JavaScript est requis pour charger ce formulaire. Appelez'} <a href="tel:${PHONE_URI}">${PHONE}</a>.</noscript></div></div></section></main>${footer(lang)}`;return shell({lang,title:t?'Contact PTS Appliance Repair | Book a Service Call':'Contactez PTS Appliance Repair | Réserver un service',description:t?`Contact PTS Appliance Repair at ${PHONE} for appliance repair across Toronto and the GTA.`:`Contactez PTS Appliance Repair au ${PHONE} pour une réparation dans Toronto et le Grand Toronto.`,canonical,alternates:`<link rel="alternate" hreflang="en" href="${DOMAIN}/en/contact.html"><link rel="alternate" hreflang="fr" href="${DOMAIN}/fr/contact.html"><link rel="alternate" hreflang="x-default" href="${DOMAIN}/en/contact.html">`,body})}
