const elfsightCss = `.elfsight-booking{padding:0;overflow:hidden;gap:0}.contact-summary{padding:25px;background:#f8fafc;border-bottom:1px solid var(--line)}.contact-summary h2{font-size:1.55rem;line-height:1.15;margin:8px 0 20px}.contact-row{display:flex;gap:12px;padding:11px 0;border-top:1px solid var(--line)}.contact-row>b{color:var(--accent);font-size:1.1rem}.contact-row div{min-width:0}.contact-row small{display:block;color:var(--dark);font-weight:850;text-transform:uppercase;letter-spacing:.06em}.contact-row a{display:block;color:var(--accent);font-weight:800;overflow-wrap:anywhere}.contact-row p{font-size:.79rem;line-height:1.45;margin:3px 0;color:var(--muted)}.contact-facts{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.contact-facts span{padding:6px 9px;border-radius:7px;background:#fce7f3;color:var(--accent);font-size:.75rem;font-weight:850}.elfsight-pane{min-height:220px;padding:12px;background:#fff}.elfsight-pane noscript{display:block;padding:20px}.elfsight-pane noscript a{color:var(--accent);font-weight:800}`;
const contactPageCss = `.contact-page{background:linear-gradient(135deg,#f8fafc,#f1f5f9);min-height:70vh}.contact-page-grid{display:grid;grid-template-columns:minmax(280px,.75fr) minmax(420px,1.35fr);gap:36px;align-items:start}.contact-info-panel{padding:10px 26px 20px 0}.contact-info-panel h1{font-size:clamp(2.6rem,5vw,4.4rem);line-height:1;margin:10px 0 18px;letter-spacing:-.05em}.contact-lead{color:var(--muted);font-size:1.08rem;margin-bottom:30px}.contact-info-panel .contact-row{padding:20px 0}.contact-info-panel .contact-row p{font-size:.9rem}.contact-form-panel{background:#fff;border-radius:18px;padding:30px;box-shadow:var(--shadow);border-top:5px solid var(--accent);min-height:640px}.contact-form-panel h2{font-size:1.75rem;margin:0 0 18px}.contact-form-panel noscript a{color:var(--accent);font-weight:800}@media(max-width:900px){.contact-page-grid{grid-template-columns:1fr}.contact-info-panel{padding-right:0}.contact-form-panel{min-height:500px}}@media(max-width:600px){.contact-form-panel{padding:16px}.contact-page .section{padding-top:45px}}`;

function richFooter(lang){const t=lang==='en';return `<footer><div class="wrap footer-rich"><div>${logo().replace('LANG',lang)}<p>${t?'Experienced appliance technicians serving Toronto and the GTA, including electric and gas appliances.':'Techniciens expérimentés desservant Toronto et le Grand Toronto, pour les appareils électriques et au gaz.'}</p><a class="btn compact" href="tel:${PHONE_URI}">${t?'Book an appointment':'Prendre rendez-vous'}</a></div><div><h3>${t?'Services':'Services'}</h3><ul>${services.map(s=>`<li><a href="/${lang}/toronto/${s.slug}.html">${s[lang]}</a></li>`).join('')}</ul></div><div><h3>${t?'Company':'Entreprise'}</h3><ul><li><a href="#about">${t?'About us':'À propos'}</a></li><li><a href="#brands">${t?'Brands':'Marques'}</a></li><li><a href="#reviews">${t?'Reviews':'Avis'}</a></li><li><a href="mailto:${EMAIL}">Contact</a></li><li><a href="#faq">FAQ</a></li></ul></div><div><h3>${t?'Contact us':'Nous joindre'}</h3><ul><li><a href="tel:${PHONE_URI}">${PHONE}</a></li><li><a href="mailto:${EMAIL}">${EMAIL}</a></li><li>${t?HOURS_EN:HOURS_FR}</li><li>${t?'Emergency line available':'Ligne d’urgence disponible'}</li><li>${t?'Payment: Interac & cash':'Paiement : Interac et comptant'}</li><li>${t?`Diagnostic: ${DIAGNOSTIC_FEE}`:`Diagnostic : ${DIAGNOSTIC_FEE}`}</li></ul></div></div><small>© ${new Date().getFullYear()} PTS Appliance Repair</small></footer><div class="mobile-bar"><span>${t?'Same-Day Available':'Service le jour même'}</span><a href="tel:${PHONE_URI}">${t?'Call':'Appelez'} ${PHONE}</a></div>`}
function localContent(lang,s,city,citySlug){const t=lang==='en';const p=cityProfiles[citySlug];return `<section class="section local-content"><div class="wrap split local-grid"><div><span class="eyebrow">${t?`Local service in ${city}`:`Service local à ${city}`}</span><h2>${t?`${s.en} for ${city} homes`:`${s.fr} pour les résidences de ${city}`}</h2><p>${t?`PTS serves ${p.areas}, as well as nearby parts of ${city}. We work with ${p.homes}, adapting appointment details to the property and appliance location.`:`PTS dessert ${p.frAreas}, ainsi que les secteurs voisins de ${city}. Nous intervenons dans les ${p.frHomes}, en adaptant les détails du rendez-vous à la propriété et à l’emplacement de l’appareil.`}</p><p>${t?`When requesting ${s.en.toLowerCase()}, share the model number, any displayed error code and the symptoms you noticed. These details help the technician prepare for the diagnostic visit.`:`Lors de votre demande de ${s.fr.toLowerCase()}, indiquez le numéro de modèle, le code d’erreur affiché et les symptômes observés. Ces renseignements aident le technicien à préparer la visite diagnostique.`}</p></div><aside class="local-checklist"><h3>${t?'Helpful before your visit':'Utile avant la visite'}</h3><ul><li>${t?'Keep the appliance accessible':'Gardez l’appareil accessible'}</li><li>${t?'Photograph the model tag and error code':'Photographiez la plaque signalétique et le code d’erreur'}</li><li>${t?'Do not continue using an unsafe appliance':'N’utilisez pas un appareil qui semble dangereux'}</li><li>${t?'Diagnostic visit: $80':'Visite diagnostique : 80 $'}</li></ul><a class="btn" href="/${lang}/contact.html">${t?'Contact PTS':'Contactez PTS'}</a></aside></div></section>`}
function serviceDetailContent(lang,s,headingLevel='h2'){const t=lang==='en';const g=serviceGuides[s.slug][lang];const H=headingLevel;return `<section class="section service-depth"><div class="wrap"><span class="eyebrow">${t?'Practical service information':'Information pratique'}</span><${H}>${t?`Understanding your ${s.en.toLowerCase()} needs`:`Comprendre vos besoins de ${s.fr.toLowerCase()}`}</${H}><p class="depth-intro">${g.intro}</p><div class="depth-grid"><div><h3>${t?'Common problems we diagnose':'Problèmes courants diagnostiqués'}</h3><ul class="problem-list">${g.problems.map(x=>`<li><span>✓</span>${x}</li>`).join('')}</ul></div><div><h3>${t?'Appliance types we service':'Types d’appareils réparés'}</h3><ul class="type-list">${g.types.map(x=>`<li>${x}</li>`).join('')}</ul><div class="safety-box"><strong>${t?'Safety first':'La sécurité d’abord'}</strong><p>${g.safety}</p></div></div></div><div class="repair-choice"><div><span class="eyebrow">${t?'Repair or replace?':'Réparer ou remplacer?'}</span><h3>${t?'A diagnosis supports a better decision':'Un diagnostic pour mieux décider'}</h3><p>${g.replace}</p></div><div class="diagnostic-price"><small>${t?'Diagnostic visit':'Visite diagnostique'}</small><strong>${DIAGNOSTIC_FEE}</strong><span>${t?'Options explained before approved work begins.':'Options expliquées avant les travaux approuvés.'}</span></div></div></div></section>`}
const landingBase = landing;
landing = function(lang,s,city,citySlug){return landingBase(lang,s,city,citySlug).replace('<section class="section wrap faq">',serviceDetailContent(lang,s)+localContent(lang,s,city,citySlug)+'<section class="section wrap faq">')}

function serviceHub(lang,s){const t=lang==='en';const other=t?'fr':'en';const g=serviceGuides[s.slug][lang];const canonical=`${DOMAIN}/${lang}/services/${s.slug}.html`;const faqs=t?[[`Do you offer same-day ${s.en.toLowerCase()}?`,`Same-day appointments may be available Monday through Saturday, depending on technician availability and location.`],[`What is the diagnostic fee?`,`The diagnostic visit is ${DIAGNOSTIC_FEE}. We explain the findings and options before approved work begins.`],[`Which areas do you serve?`,`PTS serves Toronto, Scarborough, North York, Etobicoke, Mississauga, Brampton, Markham, Richmond Hill, Vaughan, Oakville, Ajax and Pickering.`]]:[[`Offrez-vous la ${s.fr.toLowerCase()} le jour même?`,`Des rendez-vous le jour même peuvent être disponibles du lundi au samedi, selon la disponibilité et le secteur.`],[`Quels sont les frais de diagnostic?`,`La visite diagnostique coûte ${DIAGNOSTIC_FEE}. Nous expliquons les résultats et les options avant les travaux approuvés.`],[`Quelles zones desservez-vous?`,`PTS dessert Toronto, Scarborough, North York, Etobicoke, Mississauga, Brampton, Markham, Richmond Hill, Vaughan, Oakville, Ajax et Pickering.`]];const body=`${header(lang,`/${other}/services/${s.slug}.html`)}<main><section class="hub-hero"><div class="wrap hub-hero-grid"><div><span class="eyebrow">${t?'Toronto & GTA appliance service':'Service d’électroménagers à Toronto et dans le GTA'}</span><h1>${s[lang]}</h1><p>${g.intro}</p><div class="hero-actions"><a class="btn" href="tel:${PHONE_URI}">${t?'Call':'Appelez'} ${PHONE}</a><a class="text-link" href="/${lang}/contact.html">${t?'Book online →':'Réserver en ligne →'}</a></div></div><div class="hub-appliance"><img src="/assets/images/appliances/${s.image}.webp" width="640" height="640" alt="${esc(t?`${s.en.replace(' Repair','')} appliance repaired by PTS`:`Appareil pour ${s.fr.toLowerCase()} par PTS`)}" fetchpriority="high" decoding="async"></div></div></section>${serviceDetailContent(lang,s)}<section class="section wrap service-locations"><span class="eyebrow">${t?'Choose your city':'Choisissez votre ville'}</span><h2>${t?`${s.en} across the GTA`:`${s.fr} dans le Grand Toronto`}</h2><p>${t?'Select your location for neighbourhood details, local service information and appointment options.':'Sélectionnez votre ville pour les quartiers, les renseignements locaux et les options de rendez-vous.'}</p><div class="location-cards">${cities.map(([name,slug])=>`<a href="/${lang}/${slug}/${s.slug}.html"><span>⌖</span><strong>${name}</strong><small>${t?'View local service →':'Voir le service local →'}</small></a>`).join('')}</div></section><section class="section faq wrap" id="faq"><span class="eyebrow">FAQ</span><h2>${t?'Frequently asked questions':'Questions fréquentes'}</h2>${faqs.map(([q,a])=>`<details><summary>${esc(q)}</summary><p>${esc(a)}</p></details>`).join('')}</section><section class="final-cta"><div class="wrap"><h2>${t?`Need help with your ${s.en.replace(' Repair','').toLowerCase()}?`:`Besoin d’aide avec votre appareil?`}</h2><p>${t?'Call, use WhatsApp or send the contact form to ask about availability.':'Appelez, utilisez WhatsApp ou envoyez le formulaire pour connaître les disponibilités.'}</p><a class="btn" href="/${lang}/contact.html">${t?'Request service':'Demander un service'}</a></div></section></main>${footer(lang)}`;const jsonLd=JSON.stringify([{'@context':'https://schema.org','@type':'Service',name:s[lang],serviceType:s[lang],provider:{'@type':'LocalBusiness',name:'PTS Appliance Repair',telephone:'+1-343-571-9684'},areaServed:cities.map(c=>({'@type':'City',name:c[0]})),url:canonical},{'@context':'https://schema.org','@type':'FAQPage',mainEntity:faqs.map(([q,a])=>({'@type':'Question',name:q,acceptedAnswer:{'@type':'Answer',text:a}}))},{'@context':'https://schema.org','@type':'BreadcrumbList',itemListElement:[{'@type':'ListItem',position:1,name:t?'Home':'Accueil',item:`${DOMAIN}/${lang}/`},{'@type':'ListItem',position:2,name:t?'Services':'Services',item:`${DOMAIN}/${lang}/#services`},{'@type':'ListItem',position:3,name:s[lang],item:canonical}]}]);return shell({lang,title:t?`${s.en} in Toronto & GTA | PTS Appliance Repair`:`${s.fr} à Toronto et dans le GTA | PTS`,description:t?`${s.en} across Toronto and the GTA. Common problems, appliance types, $80 diagnostic and local service areas.`:`${s.fr} à Toronto et dans le GTA. Problèmes courants, types d’appareils, diagnostic à 80 $ et zones desservies.`,canonical,alternates:`<link rel="alternate" hreflang="en" href="${DOMAIN}/en/services/${s.slug}.html"><link rel="alternate" hreflang="fr" href="${DOMAIN}/fr/services/${s.slug}.html"><link rel="alternate" hreflang="x-default" href="${DOMAIN}/en/services/${s.slug}.html">`,body,jsonLd})}
function privacyPage(lang){const t=lang==='en';const other=t?'fr':'en';const canonical=`${DOMAIN}/${lang}/privacy.html`;const body=`${header(lang,`/${other}/privacy.html`)}<main><section class="section wrap legal"><span class="eyebrow">${t?'Privacy':'Confidentialité'}</span><h1>${t?'Privacy policy':'Politique de confidentialité'}</h1><p>${t?'Last updated: August 30, 2026':'Dernière mise à jour : 30 août 2026'}</p><h2>${t?'Information we receive':'Renseignements reçus'}</h2><p>${t?'When you contact PTS by phone, email, WhatsApp or the contact form, you may provide your name, contact details, city, appliance information, message and attachments.':'Lorsque vous contactez PTS par téléphone, courriel, WhatsApp ou le formulaire, vous pouvez fournir votre nom, vos coordonnées, votre ville, les renseignements sur l’appareil, votre message et des pièces jointes.'}</p><h2>${t?'How information is used':'Utilisation des renseignements'}</h2><p>${t?'We use this information to respond, assess your service request, arrange an appointment and provide customer service. We do not sell personal information.':'Nous utilisons ces renseignements pour répondre, évaluer la demande, organiser un rendez-vous et fournir le service à la clientèle. Nous ne vendons pas les renseignements personnels.'}</p><h2>${t?'Service providers':'Fournisseurs de services'}</h2><p>${t?'The contact form is provided by Elfsight. WhatsApp links open a service operated by Meta. Information submitted through those services is also subject to their respective privacy policies.':'Le formulaire est fourni par Elfsight. Les liens WhatsApp ouvrent un service exploité par Meta. Les renseignements transmis par ces services sont également assujettis à leurs politiques de confidentialité.'}</p><h2>${t?'Retention and choices':'Conservation et choix'}</h2><p>${t?'We retain service-request information only as reasonably needed for communication, service records and applicable business obligations. You may ask to access, correct or delete your information, subject to legal requirements.':'Nous conservons les renseignements sur les demandes seulement pendant la période raisonnablement nécessaire aux communications, aux dossiers de service et aux obligations applicables. Vous pouvez demander l’accès, la correction ou la suppression, sous réserve des exigences légales.'}</p><h2>Contact</h2><p><a href="mailto:${EMAIL}">${EMAIL}</a> · <a href="tel:${PHONE_URI}">${PHONE}</a></p></section></main>${footer(lang)}`;return shell({lang,title:t?'Privacy Policy | PTS Appliance Repair':'Politique de confidentialité | PTS Appliance Repair',description:t?'Learn how PTS Appliance Repair handles contact and service-request information.':'Découvrez comment PTS Appliance Repair traite les coordonnées et demandes de service.',canonical,alternates:`<link rel="alternate" hreflang="en" href="${DOMAIN}/en/privacy.html"><link rel="alternate" hreflang="fr" href="${DOMAIN}/fr/privacy.html"><link rel="alternate" hreflang="x-default" href="${DOMAIN}/en/privacy.html">`,body})}
const bookingCss = `.whatsapp-submit{background:#25D366;box-shadow:0 8px 20px rgba(37,211,102,.22)}.whatsapp-submit:hover{background:#1fb85a}.form-contact-link{display:block;text-align:center;color:var(--accent);font-size:.83rem;font-weight:800}.form-contact-link:hover{text-decoration:underline}`;
const headerBase = header;
header = function(lang,otherHref){const t=lang==='en';const old=`<a href="/${lang}/#services">Services</a>`;const menu=`<details class="services-menu"><summary>${t?'Services':'Services'}</summary><div class="services-submenu">${services.map(s=>`<a href="/${lang}/services/${s.slug}.html">${s[lang]}</a>`).join('')}</div></details>`;return headerBase(lang,otherHref).replace('<nav aria-label=','<button class="menu-toggle" type="button" aria-expanded="false" aria-controls="primary-nav" aria-label="'+(t?'Open navigation':'Ouvrir la navigation')+'"><span></span><span></span><span></span></button><nav id="primary-nav" aria-label=').replace(old,menu)};
footer = richFooter;
const footerBase = footer;
footer = function(lang){const t=lang==='en';let html=footerBase(lang);for(const s of services)html=html.replace(`/${lang}/toronto/${s.slug}.html`,`/${lang}/services/${s.slug}.html`);return html.replace('<small>©',`<div class="footer-legal wrap"><a href="/${lang}/privacy.html">${t?'Privacy policy':'Politique de confidentialité'}</a></div><small>©`)};
const homepageBase = homepage;
homepage = function(lang){const t=lang==='en';const faq=`<section class="section wrap faq home-faq" id="faq"><span class="eyebrow">FAQ</span><h2>${t?'Appliance repair questions':'Questions sur la réparation d’électroménagers'}</h2><details><summary>${t?'How much is the diagnostic?':'Combien coûte le diagnostic?'}</summary><p>${t?`The diagnostic visit is ${DIAGNOSTIC_FEE}. Repair options are presented for approval before work begins.`:`La visite diagnostique coûte ${DIAGNOSTIC_FEE}. Les options sont présentées pour approbation avant les travaux.`}</p></details><details><summary>${t?'Do you repair gas appliances?':'Réparez-vous les appareils au gaz?'}</summary><p>${t?'Yes. PTS repairs both electric and gas household appliances.':'Oui. PTS répare les appareils ménagers électriques et au gaz.'}</p></details><details><summary>${t?'Which brands do you service?':'Quelles marques réparez-vous?'}</summary><p>${t?'We service all major appliance brands.':'Nous réparons toutes les grandes marques d’électroménagers.'}</p></details><details><summary>${t?'What payments do you accept?':'Quels paiements acceptez-vous?'}</summary><p>${t?'Interac and cash are accepted.':'Nous acceptons Interac et l’argent comptant.'}</p></details></section>`;return homepageBase(lang).replace(/Licensed technicians/g,'Diploma-trained technicians').replace(/Techniciens qualifiés/g,'Techniciens diplômés').replace('</main>',faq+'</main>')}
const trustCss = `.commitments article>b{display:inline-grid;place-items:center;width:36px;height:36px;border-radius:50%;background:#fce7f3;color:var(--accent)}.commitments h3{margin:14px 0 6px}.honesty-note{max-width:760px;margin:25px auto 0;text-align:center;color:var(--muted);font-size:.9rem}.local-content{background:#fff}.local-grid{align-items:start}.local-grid p{color:var(--muted)}.local-checklist{background:var(--dark);color:#fff;border-radius:16px;padding:28px}.local-checklist h3{margin-top:0}.local-checklist ul{padding-left:20px;margin-bottom:24px}.local-checklist li{margin:9px 0;color:#cbd5e1}.legal{max-width:850px}.legal h1{font-size:clamp(2.7rem,6vw,4.5rem);letter-spacing:-.05em}.legal h2{font-size:1.5rem;margin-top:36px}.legal p{color:#475569}.legal a{color:var(--accent);font-weight:800}.footer-legal{text-align:right;margin-top:28px}.footer-legal a{color:#94a3b8;font-size:.8rem}.footer-legal a:hover{color:#fff}`;
const depthCss = `.service-depth{background:#fff}.depth-intro{max-width:850px;color:#475569;font-size:1.08rem;margin:-18px 0 36px}.depth-grid{display:grid;grid-template-columns:1fr 1fr;gap:28px}.depth-grid>div{border:1px solid var(--line);border-radius:16px;padding:28px}.depth-grid h3{font-size:1.35rem;margin-top:0}.problem-list,.type-list{list-style:none;padding:0;display:grid;gap:10px}.problem-list li{display:flex;gap:10px}.problem-list span{color:var(--accent);font-weight:900}.type-list{grid-template-columns:1fr 1fr}.type-list li{padding:9px 10px;background:var(--bg);border-radius:8px;font-size:.9rem}.safety-box{margin-top:24px;padding:18px;background:#fff7ed;border-left:4px solid #f97316;border-radius:0 10px 10px 0}.safety-box p{margin:6px 0 0;color:#7c2d12}.repair-choice{display:grid;grid-template-columns:1fr 240px;gap:26px;align-items:center;margin-top:28px;padding:30px;background:var(--bg);border-radius:16px}.repair-choice h3{font-size:1.55rem;margin:8px 0}.repair-choice p{color:#475569}.diagnostic-price{display:grid;text-align:center;padding:22px;background:var(--dark);color:#fff;border-radius:13px}.diagnostic-price strong{font-size:2.5rem;color:#f9a8d4}.diagnostic-price span{font-size:.8rem;color:#cbd5e1}.hub-hero{padding:65px 0;background:radial-gradient(circle at 72% 40%,rgba(161,0,69,.13),transparent 28%),#f8fafc}.hub-hero-grid{display:grid;grid-template-columns:1.1fr .7fr;align-items:center;gap:60px}.hub-hero h1{font-size:clamp(3rem,6vw,5rem);line-height:1;letter-spacing:-.055em;margin:14px 0 20px}.hub-hero p{font-size:1.1rem;color:#475569}.hub-appliance{height:390px}.hub-appliance img{width:100%;height:100%;object-fit:contain;filter:drop-shadow(0 20px 18px rgba(15,23,42,.18))}.service-locations>p{color:var(--muted);margin-top:-20px}.location-cards{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-top:28px}.location-cards a{display:grid;gap:6px;padding:18px;background:#fff;border:1px solid var(--line);border-radius:11px}.location-cards a:hover{border-color:var(--accent);box-shadow:var(--shadow)}.location-cards span{color:var(--accent)}.location-cards small{color:var(--muted)}.final-cta{text-align:center;padding:70px 20px;background:var(--dark);color:#fff}.final-cta h2{font-size:clamp(2rem,4vw,3rem);margin:0}.final-cta p{color:#cbd5e1}.services-menu{position:relative}.services-menu summary{cursor:pointer;list-style:none}.services-menu summary::-webkit-details-marker{display:none}.services-menu summary::after{content:' ▾';color:var(--accent)}.services-submenu{position:absolute;top:calc(100% + 20px);left:50%;transform:translateX(-50%);width:290px;padding:10px;background:#fff;border:1px solid var(--line);border-radius:12px;box-shadow:var(--shadow);display:grid;z-index:30}.services-submenu a{padding:10px 12px;border-radius:8px}.services-submenu a:hover{background:#fce7f3}.menu-toggle{display:none;background:none;border:0;padding:8px}.menu-toggle span{display:block;width:24px;height:2px;background:var(--dark);margin:5px}@media(max-width:900px){.depth-grid,.hub-hero-grid{grid-template-columns:1fr}.hub-appliance{height:310px}.location-cards{grid-template-columns:repeat(3,1fr)}.repair-choice{grid-template-columns:1fr}.menu-toggle{display:block;margin-left:auto}header nav{display:none;position:absolute;top:70px;left:0;right:0;background:#fff;padding:20px;box-shadow:var(--shadow);flex-direction:column}header.nav-open nav{display:flex}.services-submenu{position:static;transform:none;width:100%;box-shadow:none;margin-top:10px}}@media(max-width:600px){.depth-grid{grid-template-columns:1fr}.type-list,.location-cards{grid-template-columns:1fr 1fr}.hub-appliance{height:260px}}`;
const menuJs = `document.addEventListener('DOMContentLoaded',()=>{const header=document.querySelector('header'),button=document.querySelector('.menu-toggle');if(!header||!button)return;button.addEventListener('click',()=>{const open=header.classList.toggle('nav-open');button.setAttribute('aria-expanded',String(open))});document.addEventListener('keydown',e=>{if(e.key==='Escape'){header.classList.remove('nav-open');button.setAttribute('aria-expanded','false')}})});`;
const landingWithHeroImage = landing;
landing = function(lang,s,city,citySlug){const t=lang==='en';const alt=t?`${s.en.replace(' Repair','')} appliance serviced by PTS Appliance Repair in ${city}`:`Appareil de ${s.fr.replace('Réparation de ','').replace('Réparation du ','')} réparé par PTS Appliance Repair à ${city}`;const visual=`<div class="hero-service-image hero-${s.image}"><img src="/assets/images/appliances/${s.image}.webp" width="640" height="640" alt="${esc(alt)}" decoding="async" fetchpriority="high"></div>`;let html=landingWithHeroImage(lang,s,city,citySlug).replace('<section class="hero">','<section class="hero landing-hero">').replace('<div><span class="eyebrow">','<div class="hero-copy"><span class="eyebrow">').replace('<form class="booking"',`${visual}<form class="booking"`);const oldPhone=t?` | Call ${PHONE}</h1>`:` | ${PHONE}</h1>`;const newPhone=`<span class="hero-phone">${t?'Call':'Appelez'} ${PHONE}</span></h1>`;return html.replace(oldPhone,newPhone)}
const homepageWithImages = homepage;
homepage = function(lang){let html=homepageWithImages(lang);for(const s of services){const marker=`<span>↗</span><h3>${s[lang]}</h3>`;const alt=lang==='en'?`${s.en} appliance`:`Appareil pour ${s.fr.toLowerCase()}`;html=html.replace(marker,`<span>↗</span><div class="service-image"><img src="/assets/images/appliances/${s.image}.webp" width="640" height="640" alt="${esc(alt)}" loading="lazy" decoding="async"></div><h3>${s[lang]}</h3>`)}return html}
const imageCss = `.service-card{display:flex;flex-direction:column}.service-card>span{position:absolute;align-self:flex-end}.service-image{height:190px;display:grid;place-items:center;margin:-8px 0 14px}.service-image img{width:100%;height:100%;object-fit:contain;filter:drop-shadow(0 12px 10px rgba(15,23,42,.12))}.service-card h3{margin:4px 0 6px}.service-card p{margin-top:auto}@media(max-width:600px){.service-image{height:220px}}`;
const imageFixCss = `.service-card{position:relative}`;
const heroImageCss = `.landing-hero{padding:50px 0 54px;overflow:hidden}.landing-hero .hero-grid{grid-template-columns:minmax(0,1fr) minmax(245px,.72fr) minmax(345px,.95fr);gap:24px;align-items:center}.landing-hero .hero-copy{min-width:0}.landing-hero h1{font-size:clamp(2.35rem,3.6vw,3.35rem);line-height:1.02;max-width:560px;margin-bottom:16px}.landing-hero .hero-copy>p{font-size:1rem;line-height:1.55;margin:0;max-width:520px}.landing-hero .hero-actions{margin-top:22px;gap:17px}.landing-hero .booking{padding:22px;gap:10px}.landing-hero .booking input,.landing-hero .booking select{padding:11px}.hero-phone{display:block;margin-top:14px;color:var(--accent);font-size:clamp(1rem,1.45vw,1.22rem);line-height:1.2;letter-spacing:-.01em}.hero-service-image{position:relative;width:100%;height:410px;display:flex;align-items:center;justify-content:center;pointer-events:none;animation:heroFloat 6s ease-in-out infinite}.hero-service-image::before{content:"";position:absolute;width:92%;aspect-ratio:1;border-radius:50%;background:radial-gradient(circle,rgba(161,0,69,.15),rgba(161,0,69,.035) 58%,transparent 72%);z-index:0}.hero-service-image img{position:relative;z-index:1;display:block;width:100%;height:100%;object-fit:contain;filter:drop-shadow(0 22px 18px rgba(15,23,42,.2));animation:heroReveal .7s cubic-bezier(.2,.75,.25,1) both;transition:filter .3s ease,scale .3s ease}.hero-service-image:hover img{scale:1.025;filter:drop-shadow(0 27px 21px rgba(15,23,42,.24))}.hero-microwave,.hero-range-hood{height:330px}.hero-dishwasher,.hero-washer,.hero-dryer,.hero-oven-stove{height:385px}@keyframes heroReveal{from{opacity:0;transform:translateY(22px) scale(.96)}to{opacity:1;transform:translateY(0) scale(1)}}@keyframes heroFloat{0%,100%{transform:translateY(0)}50%{transform:translateY(-6px)}}@media(max-width:1050px){.landing-hero .hero-grid{grid-template-columns:minmax(0,1fr) 220px minmax(320px,.9fr);gap:18px}.hero-service-image{height:350px}.hero-microwave,.hero-range-hood{height:290px}.landing-hero h1{font-size:clamp(2.25rem,3.8vw,3rem)}}@media(max-width:900px){.landing-hero .hero-grid{grid-template-columns:minmax(0,1fr) 260px}.landing-hero .booking{grid-column:1/-1}.hero-service-image{height:345px}.hero-microwave,.hero-range-hood{height:285px}}@media(max-width:600px){.landing-hero{padding-top:42px}.landing-hero .hero-grid{grid-template-columns:1fr}.landing-hero .hero-copy{order:1}.hero-service-image,.hero-microwave,.hero-range-hood{order:2;height:300px;width:min(310px,92%);margin:auto}.landing-hero .booking{order:3;grid-column:auto}.landing-hero h1{font-size:clamp(2.2rem,10.5vw,2.9rem)}}@media(prefers-reduced-motion:reduce){.hero-service-image,.hero-service-image img{animation:none!important;transition:none!important}}`;
const homepageSafeImages = homepage;
homepage = function(lang){return homepageSafeImages(lang).replaceAll('class="service-image"','class="service-image" style="height:200px;min-height:200px;overflow:hidden;display:flex;align-items:center;justify-content:center"').replaceAll('width="640" height="640"','width="640" height="640" style="display:block;width:auto;max-width:100%;height:180px;max-height:180px;object-fit:contain"')}
const serviceDetailContentBase=serviceDetailContent;
serviceDetailContent=function(lang,s,headingLevel='h2'){const t=lang==='en';const imageAlt=t?`Illustration of a professional ${s.en.replace(' Repair','').toLowerCase()} diagnostic`:`Illustration d’un diagnostic professionnel pour ${s.fr.toLowerCase()}`;const figure=`<figure class="context-figure"><img src="/assets/images/context/${s.image}-diagnostic.webp" width="1200" height="800" loading="lazy" decoding="async" alt="${esc(imageAlt)}"><figcaption>${t?'Illustrative diagnostic view — actual appliance models may vary.':'Vue diagnostique illustrative — les modèles d’appareils peuvent varier.'}</figcaption></figure>`;return serviceDetailContentBase(lang,s,headingLevel).replace('<div class="depth-grid">',figure+'<div class="depth-grid">')}
const homepageExperienceBase=homepage;
homepage=function(lang){return homepageExperienceBase(lang).replaceAll('Diploma-trained technicians','Experienced technicians').replaceAll('Techniciens diplômés','Techniciens expérimentés')}
const contextCss=`.context-figure{margin:0 0 34px;border-radius:18px;overflow:hidden;background:#e2e8f0;box-shadow:0 16px 38px rgba(15,23,42,.12)}.context-figure img{display:block;width:100%;height:auto;aspect-ratio:3/2;object-fit:cover}.context-figure figcaption{padding:10px 16px;background:#fff;color:var(--muted);font-size:.78rem}`;
function write(file,data){fs.mkdirSync(path.dirname(file),{recursive:true});fs.writeFileSync(file,data)}
write(path.join('assets','styles.css'),css+extraCss+businessCss+elfsightCss+contactPageCss+bookingCss+trustCss+imageCss+imageFixCss+heroImageCss+depthCss+contextCss);write(path.join('assets','app.js'),js+menuJs);
const urls=[];
for(const lang of ['en','fr']){write(path.join(lang,'index.html'),homepage(lang));urls.push(`${DOMAIN}/${lang}/`);write(path.join(lang,'contact.html'),contactPage(lang));urls.push(`${DOMAIN}/${lang}/contact.html`);write(path.join(lang,'privacy.html'),privacyPage(lang));urls.push(`${DOMAIN}/${lang}/privacy.html`);for(const s of services){write(path.join(lang,'services',`${s.slug}.html`),serviceHub(lang,s));urls.push(`${DOMAIN}/${lang}/services/${s.slug}.html`)}for(const [city,citySlug] of cities)for(const s of services){write(path.join(lang,citySlug,`${s.slug}.html`),landing(lang,s,city,citySlug));urls.push(url(lang,citySlug,s.slug));}}
write('sitemap.xml',`<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${urls.map(u=>`  <url><loc>${u}</loc></url>`).join('\n')}\n</urlset>\n`);
const imageUrls=[];for(const lang of ['en','fr'])for(const s of services)imageUrls.push(`<url><loc>${DOMAIN}/${lang}/services/${s.slug}.html</loc><image:image><image:loc>${DOMAIN}/assets/images/appliances/${s.image}.webp</image:loc></image:image><image:image><image:loc>${DOMAIN}/assets/images/context/${s.image}-diagnostic.webp</image:loc></image:image></url>`);
write('image-sitemap.xml',`<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9" xmlns:image="http://www.google.com/schemas/sitemap-image/1.1">\n${imageUrls.join('\n')}\n</urlset>\n`);
write('robots.txt',`User-agent: *\nAllow: /\n\nSitemap: ${DOMAIN}/sitemap.xml\nSitemap: ${DOMAIN}/image-sitemap.xml\n`);
console.log(`Built ${urls.length} HTML pages, 14 service hubs, sitemap.xml, image-sitemap.xml, robots.txt and shared assets.`);
